import { user } from "@app/model";
import { ButtonConfirm, Log, useProxyWatch, useTranslation } from "@fanfanlo";
import { autoWebViewJs } from '@droid/android';
import { Button, Box } from "@mui/material";

const fileLog = new Log(false, 'LogoutButton_f')
fileLog.pause = true;
fileLog.childrenPaused = true;
export function LogoutButton(){
    const { t } = useTranslation('homepage/components/logout/content');
    const onSignoutClick = () => {
        user.signout();
        // 通知安卓端退出
        const script = `com.fanfanlo.droid.auth.FirebaseAuthManager.logout()`;
        autoWebViewJs.callScript(script);
    }   
    return(
        
                    <Box>
                        {/* <Box>
                            <span>
                                {user.userName}
                            </span>
                        </Box> */}
                        <Box>
                        <span>
                            <ButtonConfirm
                              title={t('LogoutButton.confirmTitle')}
                              content={t('LogoutButton.confirmContent')}
                              onConfirm={onSignoutClick}
                              data-testid="LogoutButton__confirmDialog__01aryz6s610p4z0skjq69x5prt"
                              data-test-comment="退出登录确认对话框，用户点击退出按钮后弹出，需要用户确认才能执行退出"
                            >
                              <Button
                                data-testid="LogoutButton__signOutButton__01aryz6s610p4z0skjq69x5pru"
                                data-test-comment="退出登录按钮，点击后弹出确认对话框，确认后调用 Firebase 退出接口"
                              >
                                {t('LogoutButton.signOut')}
                              </Button>
                            </ButtonConfirm>
                        </span>
                        </Box>
                    </Box>
    )
}

export function LogoutButtonBox(){
    const [userToken] = useProxyWatch(user, 'data.storeData.user_token', user.data.storeData.user_token);
    fileLog.log('LogoutButtonBox userToken=', userToken);
    fileLog.log('LogoutButtonBox userToken=', user);
    if(!userToken){
        return <></>;
    }   
    return(
        <Box><LogoutButton /></Box>
    )   
}